ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
import validate_compatibility_synthetic as m
import collect_compatibility_synthetic as c

def read(name):
    with (m.OUT/name).open(newline='',encoding='utf-8-sig') as f:return list(csv.DictReader(f))
summary=read('synthetic_summary.csv');contrasts=read('real_vs_synthetic.csv');gate=json.loads((m.OUT/'reproduction_gate.json').read_text());oracle=read('synthetic_oracle_noise.csv')
