    combined.append(dict(setting='/'.join(r[k] for k in ['family','subset','architecture','policy','variant']),fitting_engines=r['fitting_engines'],evaluation_engines=r['evaluation_engines'],fitting_replications=r['fitting_replications'],incompatibility_rate=r['incompatibility_rate'],rate_ci_low=r['incompatibility_rate_lo'],rate_ci_high=r['incompatibility_rate_hi'],mean_distance=r['mean_distance'],distance_ci_low=r['mean_distance_lo'],distance_ci_high=r['mean_distance_hi']))
