m.write(m.OUT/'final_manifest.json',dict(status='COMPLETE',protocol=m.check_lock(),files={p.name:m.sha(p) for p in m.OUT.iterdir() if p.suffix in ['.csv','.md','.json','.png','.pdf'] and p.name!='final_manifest.json'},script_sha256=m.sha(__file__)))
